<?php use App\Support\Ui; $details=[['Candidate',$interview['candidate_name']],['Candidate phone',$interview['candidate_phone']??'Removed with candidate account'],['Technology',$interview['technology_name']],['Interview round',$interview['interview_round']],['Interview type',ucfirst(strtolower($interview['interview_type']))],['Assigned resource',$interview['resource_name']],['Support person',$interview['support_person_name']??'Not required'],['HR details',$interview['hr_unavailable']?'Not available':$interview['hr_name'].' · '.$interview['hr_phone']]]; ?>
<div class="page-heading"><div><a class="back-link" href="<?= $e($url('admin/interviews')) ?>">← Interviews</a><span class="eyebrow">BOOKING #<?= $e($interview['id']) ?></span><h1><?= $e($interview['company_name']) ?></h1><p><?= $e($interview['candidate_name']) ?> · <?= $e($interview['job_role']) ?><?php if($interview['candidate_deleted']):?> <span class="deleted-label">Deleted candidate</span><?php endif;?></p></div><span class="badge <?= $interview['status']==='BOOKED'?'green':'danger-badge' ?>"><?= $e(ucfirst(strtolower($interview['status']))) ?></span></div>
